"use client";
/* Spud, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Spud(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("spud"); }, []);
  return React.createElement("piix-sprite", { "name": "spud", ...piixAttrs(props) });
}

export default Spud;
